                                                ; MemViewerDrawList ...
        resb 4
MemViewKey:                                     ; memory viewer last key; used by MemViewerLoop,
                                                ; MemViewerSelectRow
        resb 4
MemViewFlags:                                   ; memory viewer flags; used by MemViewerLoop,
                                                ; MemViewerSelectRow
